window.__CRICPRO_V4_SRC=(window.__CRICPRO_V4_SRC||"")+"esc(a?.name)} vs ${esc(b?.name)}</b><span class=\"badge ${m.status}\">${esc(m.status||'setup')}</span></div><small>${m.overs} overs • ${esc(m.type)} • ${esc(R.profile(m.profileId).name)}</small>${score?`<strong class=\"miniScore\">${score}</strong>`:''}${m.result?`<div class=\"resultline\">${esc(m.result)}</div>`:''}</button>`}\nfunction events(){return `<div class=\"pagehead\"><div><h2>Competitions</h2><p>League and knockout setup.</p></div><button class=\"btn primary small\" data-act=\"newEvent\">＋</button></div><div class=\"list\">${db.competitions.length?db.competitions.map(c=>`<button class=\"listitem\" data-event=\"${c.id}\"><div class=\"row between\"><b>${esc(c.name)}</b><span class=\"badge\">${esc(c.format)}</span></div><small>${c.teamIds.length} teams • ${c.overs} overs</small></button>`).join(''):'<div class=\"empty\">No competitions yet.</div>'}</div>`}\nfunction stats(){let bat={},bowl={};for(const m of db.matches)for(const i of m.innings||[]){for(const pid of i.battingXI||[]){bat[pid]=bat[pid]||{name:playerName(pid),v:0};bat[pid].v+=R.batterFigures(i,pid).runs}for(const pid of i.bowlingXI||[]){bowl[pid]=bowl[pid]||{name:playerName(pid),v:0};bowl[pid].v+=R.bowlerFigures(i,pid).wickets}}const top=o=>Object.values(o).sort((a,b)=>b.v-a.v).slice(0,10);return `<h2>Statistics</h2><div class=\"statgrid\"><div class=\"card\"><small>Matches</small><strong>${db.matches.length}</strong></div><div class=\"card\"><small>Teams</small><strong>${db.teams.length}</strong></div><div class=\"card\"><small>Completed</small><strong>${db.matches.filter(m=>m.status==='done').length}</strong></div></div>${leader('Top Run Scorers',top(bat),'Runs')}${leader('Top Wicket Takers',top(bowl),'Wkts')}`}\nfunction leader(title,a,col){return `<div class=\"sectiontitle\">${title}</div><div class=\"card tablewrap\"><table><tr><th>Player</th><th>${col}</th></tr>${a.map(x=>`<tr><td>${esc(x.name)}</td><td><b>${x.v}</b></td></tr>`).join('')||'<tr><td colspan=\"2\">No data</td></tr>'}</table></div>`}\n\n// TEAM MANAGEMENT\nfunction newTeam(){modal(`<div class=\"modalhead\"><h2>New Team</h2><button class=\"iconbtn\" data-act=\"close\">✕</button></div><div class=\"field\"><label>Team name</label><input id=\"tn\" autocomplete=\"off\" placeholder=\"e.g. Indore Strikers\"></div><div class=\"field\"><label>Short name</label><input id=\"ts\" maxlength=\"5\" placeholder=\"IND\"></div><div class=\"field\"><label>Players — one per line</label><textarea id=\"tp\" rows=\"9\" placeholder=\"Player 1\\nPlayer 2\\nPlayer 3\"></textarea></div><button class=\"btn primary block\" data-act=\"saveTeam\">Save Team</button>`)}\nfunction saveTeam(){const name=$('tn')?.value.trim(),short=$('ts')?.value.trim(),raw=$('tp')?.value||'';if(!name)return toast('Enter team name');const names=raw.split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean);if(names.length<2)return toast('Add at least 2 players');if(db.teams.some(t=>t.name.toLowerCase()===name.toLowerCase()))return toast('Team already exists');db.teams.push({id:uid(),name,short:(short||name.slice(0,3)).toUpperCase(),players:names.map(n=>({id:uid(),name:n,role:'Player'}))});save();closeModal();render();toast('Team saved')}\nfunction editTeam(id){const t=team(id);if(!t)return;modal(`<div class=\"modalhead\"><div><h2>${esc(t.name)}</h2><p>${t.players.length} players</p></div><button class=\"iconbtn\" data-act=\"close\">✕</button></div><div class=\"playerlist\">${t.players.map(p=>`<div class=\"playerrow\"><div><b>${esc(p.name)}</b><small>${esc(p.role||'Player')}</small></div><button class=\"iconbtn\" data-remove-player=\"${p.id}\" data-team-id=\"${t.id}\">✕</button></div>`).join('')}</div><div class=\"field\"><label>Add player</label><input id=\"newp\" placeholder=\"Player name\"></div><button class=\"btn primary block\" data-add-player=\"${t.id}\">Add Player</button>`,true)}\nfunction addPlayer(tid){const t=team(tid),n=$('newp')?.value.trim();if(!t||!n)return;if(t.players.some(p=>p.name.toLowerCase()===n.toLowerCase()))return toast('Player already exists');t.players.push({id:uid(),name:n,role:'Player'});save();closeModal();editTeam(tid)}\nfunction removePlayer(tid,pid){const t=team(tid);if(!t)return;if(t.players.length<=2)return toast('Keep at least 2 players');t.players=t.players.filter(p=>p.id!==pid);save();closeModal();editTeam(tid)}\nfunction importCSV(){const f=$('csvFile')?.files?.[0];if(!f)return toast('Choose a CSV file');const r=new FileReader();r.onload=()=>{let count=0;const lines=String(r.result).split(/\\r?\\n/).filter(Boolean);if(lines[0]&&/team/i.test(lines[0]))lines.shift();for(const line of lines){const [tn,pn,role]=line.split(',').map(x=>(x||'').trim());if(!tn||!pn)continue;let t=db.teams.find(x=>x.name.toLowerCase()===tn.toLowerCase());if(!t){t={id:uid(),name:tn,short:tn.slice(0,3).toUpperCase(),players:[]};db.teams.push(t)}if(!t.players.some(p=>p.name.toLowerCase()===pn.toLowerCase())){t.players.push({id:uid(),name:pn,role:role||'Player'});count++}}save();render();toast(`${count} players imported`)};r.onerror=()=>toast('Could not read CSV');r.readAsText(f)}\n\n// MATCH SETUP\nfunction newMatch(preset=null){if(db.teams.length<2){toast('Create at least 2 teams first');nav('teams');return}modal(`<div class=\"modalhead\"><h2>New Match</h2><button class=\"iconbtn\" data-act=\"close\">✕</button></div><div class=\"field\"><label>Match type</label><select id=\"mt\"><option>Single Match</option><option>League</option><option>Tournament</option><option>Knockout</option><option>Practice</option></select></div><div class=\"twocol\"><div class=\"field\"><label>Team A</label><select id=\"ma\">${teamOptions()}</select></div><div clas";